CREATE OR REPLACE FUNCTION public.sellerpilot_gateway_queue_pulse(p_token_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_queued integer;
  v_stale_running integer;
begin
  if not sellerpilot_private.worker_token_has_scope(p_token_hash, 'gateway', true) then
    raise exception 'invalid worker token' using errcode = '42501';
  end if;

  -- Only jobs the serverless lane refuses can reach this machine, so jobs the
  -- serverless lane accepts must not keep this worker awake.
  select count(*) into v_queued
    from sellerpilot_private.channel_gateway_jobs j
   where j.status = 'queued'
     and not sellerpilot_private.serverless_gateway_job_allowed(j.channel, j.operation);

  select count(*) into v_stale_running
    from sellerpilot_private.channel_gateway_jobs
   where status = 'running'
     and (lease_expires_at is null or lease_expires_at <= clock_timestamp());

  return jsonb_build_object('queued', v_queued, 'staleRunning', v_stale_running);
end;
$function$
